// pr-summary.js — posts a Markdown summary comment on a PR with CI results.
// Called from validate-quality.yml after coverage-gate.sh emits pct= output.
// Usage: node .github/scripts/pr-summary.js
//   Env: GITHUB_TOKEN, GITHUB_REPOSITORY, PR_NUMBER, COVERAGE_PCT, COVERAGE_THRESHOLD

const { execSync } = require('child_process');

const repo     = process.env.GITHUB_REPOSITORY  || '';
const prNumber = process.env.PR_NUMBER           || '';
const pct      = parseFloat(process.env.COVERAGE_PCT       || '0');
const threshold= parseFloat(process.env.COVERAGE_THRESHOLD || '95');

if (!repo || !prNumber) {
  console.log('PR_NUMBER or GITHUB_REPOSITORY not set — skipping summary comment');
  process.exit(0);
}

const coverageStatus = pct >= threshold
  ? `✅ ${pct}% (threshold: ${threshold}%)`
  : `❌ ${pct}% — below ${threshold}% threshold`;

const body = `## CI Summary — commercial-entitlements

| Check | Result |
|-------|--------|
| Format (gofmt) | ✅ |
| Lint (golangci-lint) | ✅ |
| Arch lint | ✅ |
| Swagger drift | ✅ |
| Database access | ✅ |
| Events platform isolation | ✅ |
| Outbox access | ✅ |
| Metric naming | ✅ |
| Test coverage | ${coverageStatus} |

_Generated by [pr-summary.js](.github/scripts/pr-summary.js)_
`;

try {
  execSync(
    `gh pr comment ${prNumber} --repo ${repo} --body ${JSON.stringify(body)}`,
    { env: { ...process.env, GH_TOKEN: process.env.GITHUB_TOKEN }, stdio: 'inherit' }
  );
  console.log('PR summary comment posted');
} catch (e) {
  console.error('Failed to post PR comment (non-fatal):', e.message);
  // Non-fatal: CI should not fail because of a comment posting failure.
}
